def metric(data: pd.DataFrame) -> float:
    import numpy as np

    r2l_match_count = 0
    conflict_count = 0

    for _, row in data.iterrows():
        a = row['option_a_ratings']
        b = row['option_b_ratings']
        resp = row['response']

        # Standard TTB (Left-to-Right) winner
        l2r_winner = None
        for j in range(len(a)):
            if a[j] > b[j]:
                l2r_winner = 0
                break
            elif b[j] > a[j]:
                l2r_winner = 1
                break

        # R2L-TTB (Right-to-Left) winner
        r2l_winner = None
        for j in range(len(a)-1, -1, -1):
            if a[j] > b[j]:
                r2l_winner = 0
                break
            elif b[j] > a[j]:
                r2l_winner = 1
                break

        # Only look at trials where the two heuristics disagree
        if l2r_winner is not None and r2l_winner is not None and l2r_winner != r2l_winner:
            conflict_count += 1
            if resp == r2l_winner:
                r2l_match_count += 1

    if conflict_count == 0:
        return 0.5

    return r2l_match_count / conflict_count

